#!/usr/bin/env python3
import os
import sys
import json
import logging
import requests

# Setup logging
os.makedirs("/app/logs", exist_ok=True)
logging.basicConfig(
    filename="/app/logs/app.log",
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(message)s"
)
logger = logging.getLogger(__name__)

API_BASE = os.environ.get("API_BASE", "http://127.0.0.1:5000")
TOKEN_FILE = "/app/tokens.json"
DEFAULT_USERNAME = "admin"
DEFAULT_PASSWORD = "password123"

def load_tokens():
    """Load tokens from file."""
    if os.path.exists(TOKEN_FILE):
        with open(TOKEN_FILE) as f:
            return json.load(f)
    return {}

def save_tokens(tokens):
    """Save tokens to file."""
    with open(TOKEN_FILE, "w") as f:
        json.dump(tokens, f, indent=2)

def acquire():
    """Login and acquire tokens, save to tokens.json."""
    logger.info("Acquiring tokens")
    resp = requests.post(f"{API_BASE}/auth/login", json={
        "username": DEFAULT_USERNAME,
        "password": DEFAULT_PASSWORD
    })
    if resp.status_code != 200:
        logger.error(f"Failed to acquire tokens: {resp.text}")
        print(f"Error: {resp.text}")
        sys.exit(1)
    data = resp.json()
    save_tokens(data)
    print("Tokens acquired successfully")
    print(json.dumps(data, indent=2))

def validate():
    """Validate a token from tokens.json."""
    tokens = load_tokens()
    if not tokens or "access_token" not in tokens:
        print("No tokens found. Run 'acquire' first.")
        sys.exit(1)

    logger.info("Validating token")
    resp = requests.get(f"{API_BASE}/auth/validate", headers={
        "Authorization": f"Bearer {tokens['access_token']}"
    })
    print(f"Status: {resp.status_code}")
    print(resp.json())
    if resp.status_code != 200:
        sys.exit(1)

def revoke():
    """Revoke a token and update tokens.json."""
    tokens = load_tokens()
    if not tokens or "access_token" not in tokens:
        print("No tokens found. Run 'acquire' first.")
        sys.exit(1)

    token_to_revoke = tokens.get("access_token")
    logger.info("Revoking token")
    resp = requests.post(f"{API_BASE}/auth/revoke", json={"token": token_to_revoke})
    if resp.status_code != 200:
        logger.error(f"Failed to revoke token: {resp.text}")
        print(f"Error: {resp.text}")
        sys.exit(1)

    print("Token revoked successfully")
    print(resp.json())

    # Update tokens file to mark as revoked
    tokens["revoked"] = True
    save_tokens(tokens)

def retry():
    """Retry acquiring tokens if expired."""
    tokens = load_tokens()
    if tokens and tokens.get("access_token"):
        # Check if expired by validating
        resp = requests.get(f"{API_BASE}/auth/validate", headers={
            "Authorization": f"Bearer {tokens['access_token']}"
        })
        if resp.status_code == 200:
            print("Token is still valid")
            print(resp.json())
            return
        elif resp.status_code == 403:
            print("Token has been revoked")
        else:
            print(f"Token issue: {resp.json()}")

    print("Acquiring new tokens...")
    acquire()

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python cli.py <command>")
        print("Commands: acquire, validate, revoke, retry")
        sys.exit(1)

    command = sys.argv[1]
    if command == "acquire":
        acquire()
    elif command == "validate":
        validate()
    elif command == "revoke":
        revoke()
    elif command == "retry":
        retry()
    else:
        print(f"Unknown command: {command}")
        sys.exit(1)
PYEOF
